SELECT COUNT(*) AS recent_count
FROM public.player_stats
WHERE first_seen >= NOW() - INTERVAL '1 DAYS';

SELECT COUNT(*) AS recent_count
FROM public.player_stats
WHERE first_seen >= NOW() - INTERVAL '1 HOURS';

SELECT COUNT(*) AS recent_count
FROM public.player_stats
WHERE last_seen >= NOW() - INTERVAL '1 HOURS';

SELECT 
  (SELECT SUM(kills) FROM public.player_stats) * 1.0 / 
  NULLIF((SELECT SUM(deaths) FROM public.player_stats), 0) AS kill_death_ratio;

SELECT COUNT(*) AS recent_count
FROM public.player_stats
WHERE last_seen >= NOW() - INTERVAL '7 DAYS';

SELECT COUNT(*) AS recent_count
FROM public.player_stats
WHERE first_seen >= NOW() - INTERVAL '7 DAYS';

SELECT COUNT(*) AS recent_count
FROM public.player_stats
